// Regenerate specs/carin-bb-2.2.0.yaml from the IG's published CapabilityStatement.
// Source: https://hl7.org/fhir/us/carin-bb/CapabilityStatement-c4bb.json (recorded in specs/source/).
import { join } from 'node:path';
import { ROOT, readJson, writeYaml } from '../src/io.ts';
import { specFromCapabilityStatement } from '../src/spec.ts';

const source = join(ROOT, 'specs/source/carin-bb-2.2.0-CapabilityStatement.json');
const spec = specFromCapabilityStatement(readJson(source), 'carin-bb');
writeYaml(
  join(ROOT, 'specs/carin-bb-2.2.0.yaml'),
  spec,
  '# GENERATED by scripts/import-spec.ts from the CARIN IG CapabilityStatement. Do not edit by hand.',
);
console.log(`spec ${spec.spec.id} ${spec.spec.version}: ${Object.keys(spec.resources).length} resources`);
